Type: C<Enum> (L<Google::Cloud::Ces::V1::ExportAppRequest::ExportFormat>)

Required. The format to export the app in.

=item * C<< $msg->gcs_uri() >> / C<< $msg->gcs_uri($value) >>

Type: C<String>

Optional. The [Google Cloud
Storage](https://cloud.google.com/storage/docs/) URI to which to export the
app. The format of this URI must be `gs://<bucket-name>/<object-name>`. The
exported app archive will be written directly to the specified GCS object.

=item * C<< $msg->app_version() >> / C<< $msg->app_version($value) >>

Type: C<String>

Optional. The resource name of the app version to export.
Format:
`projects/{project}/locations/{location}/apps/{app}/versions/{version}`.

=back

=head3 Enum: ExportAppRequest::ExportFormat

=over 4

=item * C<EXPORT_FORMAT_UNSPECIFIED> => C<0>

=item * C<JSON> => C<1>

=item * C<YAML> => C<2>

=back

